  return { total: books.length, read, toRead: books.length - read, percent: books.length ? Math.round((read / books.length) * 100) : 0 };
}

const s = readingStats([{"read":true},{"read":false},{"read":false}]);
console.log(s.read, s.toRead, s.percent + "%");

